from pathlib import Path
r=Path.cwd()
def edit(name,old,new):
 p=r/name;s=p.read_text();assert old in s,name;p.write_text(s.replace(old,new,1),encoding='utf-8',newline='\n')
edit('CMakeLists.txt','tests/editor/layout_authoring_tests.cpp)','tests/editor/layout_authoring_tests.cpp tests/editor/container_tests.cpp)')
edit('CMakeLists.txt','LAYOUT-POLICY LAYOUT-GEOMETRY)','LAYOUT-POLICY LAYOUT-GEOMETRY CONTAINER-SCENES CONTAINER-GEOMETRY CONTAINER-RULES CONTAINER-ATOMIC CONTAINER-POLICY CONTAINER-COMPAT)')
edit('CMakeLists.txt','        add_test(NAME native.EDITOR-LAYOUT', '''        add_test(NAME native.EDITOR-CONTAINERS COMMAND "${Python3_EXECUTABLE}" "${CMAKE_SOURCE_DIR}/tests/editor/native_containers.py"
            "$<TARGET_FILE:syspane_editor_window>" "$<TARGET_FILE:syspane_editor_exit_probe>" "${CMAKE_BINARY_DIR}/native-evidence")
        set_tests_properties(native.EDITOR-CONTAINERS PROPERTIES TIMEOUT 600)
        add_test(NAME native.EDITOR-LAYOUT''')
edit('tests/editor/editor_draft_tests.cpp','void run_layout_authoring(', 'void run_container(const std::string&,const std::string&);\nvoid run_layout_authoring(')
