edit('build-support/components.json','"tests/editor/layout_authoring_tests.cpp"','"tests/editor/layout_authoring_tests.cpp",\n        "tests/editor/container_tests.cpp"')
edit('tests/editor/native_editor.py','properties=False,layout=False):','properties=False,layout=False,container=False):')
edit('tests/editor/native_editor.py','sum((large,arrange,group,snap,properties,layout))','sum((large,arrange,group,snap,properties,layout,container))')
edit('tests/editor/native_editor.py','self.layout=layout;','self.container=container;self.layout=layout;')
edit('tests/editor/native_editor.py',"ROOT/('tests/editor/layout-authoring-cases.json'", "ROOT/('tests/editor/container-cases.json' if container else 'tests/editor/layout-authoring-cases.json'")
edit('tests/editor/native_editor.py','("layout-" if self.layout','("container-" if self.container else "layout-" if self.layout')
