edit('tests/editor/editor_window.cpp','content=true;layout_mode=', 'content=true;container_mode=mode.substr(0,10)=="container-";layout_mode=')
edit('tests/editor/editor_window.cpp','behavior=layout_mode?', 'behavior=container_mode?mode.substr(10):layout_mode?')
edit('tests/editor/editor_window.cpp','root+(layout_mode?', 'root+(container_mode?"/tests/editor/container-cases.json":layout_mode?')
edit('tests/editor/editor_window.cpp','if(behavior=="retain-layout")', 'if(behavior=="retain-container"){canary=gtk_label_new("Retained container canary Private container");gtk_box_pack_start(GTK_BOX(box),canary,FALSE,FALSE,0);}\n        if(behavior=="retain-layout")')
edit('tests/editor/editor_window.cpp','if(behavior=="wrong-layout")','if(behavior=="wrong-container"){auto changed=c::parse_command(body);auto& children=changed["operations"][0]["scene"]["widgets"].back()["children"];std::reverse(children.begin(),children.end());body=changed.dump();}\n            if(behavior=="wrong-layout")')
edit('tests/editor/editor_window.cpp','need(layout_mode,"layout laboratory control")','need(layout_mode||container_mode,"layout laboratory control")')
for old,new in [('layout_step.py','container_step.py'),('layout_flow.py','container_flow.py')]:
 s=(r/'out/campaign'/old).read_text().replace('w-10-layout-authoring','w-10-containers').replace('layout_step.py','container_step.py').replace('layout-execution-','container-execution-')
 s=s.replace("('layout','calibration'", "('containers','layout','calibration'")
 if old.endswith('step.py'):
  s=s.replace("command={'layout':", "command={'containers':['ctest','--preset',profile,'-R','^native[.]EDITOR-CONTAINERS$','--output-on-failure'],'layout':")
  s=s.replace("artifact_name={'layout':", "artifact_name={'containers':'syspane_editor_window','layout':")
  s=s.replace("'^editor[.]LAYOUT-'", "'^editor[.]CONTAINER-'")
 (r/'out/campaign'/new).write_text(s,encoding='utf-8',newline='\n')
print('Registered portable and native container checks.')
